/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-avatar> - a silhouette beside a name, and an empty slot that looks empty.
 *
 *   <ov-avatar kind="human" variant="female" name="CDR" task="FLYING RMS" status="ok"></ov-avatar>
 *   <ov-avatar kind="robot" variant="drone" name="ARM-2"></ov-avatar>
 *   <ov-avatar></ov-avatar>                       an unassigned slot
 *
 * FILLED SILHOUETTES ONLY, in a dark theme-derived tone with a slight vertical
 * gradient (--ov-av-top, --ov-av-bottom), cropped by their well, with no inner
 * detail (no eyes, visors or panel lines): the outer edge alone says what the
 * figure is.
 *   human  neutral (the default), female, male
 *   crew   a helmeted suit
 *   alien  grey, insect, squid, reptile
 *   robot  box, android, drone, mech
 * No faces, no likeness, nothing that could be read as a particular person.
 * A human with no `variant` is the non-gendered one, which claims least.
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 AN EMPTY SLOT IS NEVER DRAWN AS SOMEONE. The one false thing an avatar
 * beside a name can say is that a seat is filled, so an unassigned slot has
 * its OWN drawing, a dashed empty well with nothing in it, and there is no
 * default silhouette for a missing kind. A human outline in an empty seat is
 * the lie; a stock "person" icon is exactly that outline.
 *
 * And four that follow from it:
 *
 * 1. A NAME WITH NO KIND IS NOT A HUMAN. It is drawn as a dotted well with a
 *    question mark and says KIND NOT STATED, rather than picking the likeliest
 *    silhouette.
 * 2. A SILHOUETTE WITH NO NAME SAYS NAME NOT GIVEN. Someone is in the seat and
 *    nobody said who, which is a refusal, not a blank.
 * 3. A NAME HANDED TO A SLOT MARKED UNASSIGNED IS A CONTRADICTION and is shown
 *    as one; neither the name nor the empty seat is picked.
 * 4. THE STATUS MARK IS SUPPLIED, NEVER DECIDED. The avatar draws `status`
 *    (ok, note, bad, unknown) as a shape on its edge and derives nothing. A
 *    status handed to an empty slot is not drawn, because nobody is there to
 *    be well or unwell, and the refusal is written out. Each mark differs in
 *    FORM: a filled disc, a ring, a filled diamond, a hollow square.
 *
 * A `variant` this kind does not have is said in words, and the kind's first
 * variant is drawn: the kind was stated, only its drawing was not.
 *
 * `task` is the second line (what they are doing). It is not `role`, which is
 * the host's ARIA role and belongs to the platform.
 *
 * No timers, no animation frames: it redraws on an attribute change.
 */

import { define } from '../../../src/ov-core.js';

/* 100-unit well. Every drawing is a FILLED SILHOUETTE with no inner detail:
 * no eyes, no visor, no panel lines, nothing cut out of the fill. What makes
 * one kind different from another is its outer edge alone. `b` is a filled
 * shape, `limb` a thin part (antenna, tentacle, leg) drawn as a heavy stroke
 * in the same colour, which is still edge, not detail. Every drawing reaches
 * the well's lower edge, where the clip crops it like a portrait. */
const b = (d) => `<path class="ov-avatar__body" d="${d}"/>`;
const limb = (d) => `<path class="ov-avatar__limb" d="${d}"/>`;
const disc = (cx, cy, r) => `<circle class="ov-avatar__body" cx="${cx}" cy="${cy}" r="${r}"/>`;
const box = (x, y, w, h, rx = 0) => `<rect class="ov-avatar__body" x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}"/>`;

/* A left-right symmetric outline: the right half is given as cubic segments
 * from the top centre (50, top) down to the bottom, and the left half is its
 * mirror, drawn back up. Both sides of a figure are the same by construction. */
function sym(top, segs) {
  let d = `M50 ${top}`;
  for (const s of segs) d += `C${s.join(' ')}`;
  const pts = [[50, top], ...segs.map((s) => [s[4], s[5]])];
  const [lx, ly] = pts[pts.length - 1];
  d += `L${100 - lx} ${ly}`;
  for (let i = segs.length - 1; i >= 0; i--) {
    const [c1x, c1y, c2x, c2y] = segs[i];
    const [px, py] = pts[i];
    d += `C${100 - c2x} ${c2y} ${100 - c1x} ${c1y} ${100 - px} ${py}`;
  }
  return `${d}Z`;
}

/* Human proportions, in well units: a head about 34 wide and 50 tall, a neck
 * about 60% of the head's width that leaves the head under the jaw's angle,
 * runs down about a fifth of the head's height, and only then flares into the
 * trapezius, which slopes out to the shoulder before the deltoid rounds down.
 * Seen from the front the neck is wide (about two thirds of the head) and
 * short, and the jaw rounds into it rather than pinching in above it. */
const KINDS = {
  human: {
    name: 'human',
    variants: {
      // Hair over the ears to the jaw; neck and shoulders between the others.
      neutral: b(sym(10, [
        [62, 10, 69, 17, 69, 29], [69.5, 37, 69, 42, 67, 47], [65.5, 51, 63, 54, 61, 55.5],
        [61, 59, 61.5, 62, 62, 64], [67, 67, 75, 69, 82, 71], [90, 73, 95, 80, 96, 90], [96, 94, 96, 97, 96, 100]])),
      // Long hair to the shoulders, tapering in where it meets them; narrower
      // shoulders. The neck is behind the hair.
      female: b(sym(9, [
        [62, 9, 70, 17, 70, 29], [71, 40, 70, 50, 72, 59], [73, 63, 72, 66, 69, 67],
        [67.5, 67.5, 66, 68, 65, 69], [71, 71, 79, 72, 86, 75], [92, 78, 94, 85, 94, 92], [94, 95, 94, 98, 94, 100]])),
      // Short hair, ears showing, the widest neck and the broadest, flattest shoulders.
      male: b(sym(10, [
        [62, 10, 68, 17, 68, 28], [70.5, 27, 72.5, 30, 72, 35], [71.6, 40, 70, 43, 68, 43],
        [67, 49, 65, 53, 62, 55.5], [62, 59, 62.5, 62, 63, 64], [68, 67, 76, 69, 84, 71],
        [92, 73, 97, 80, 98, 90], [98, 94, 98, 97, 98, 100]])),
    },
  },
  crew: {
    name: 'helmeted crew',
    variants: {
      // Helmet, neck ring, a life-support pack standing above bulky shoulders.
      suit: disc(50, 34, 24) + box(38, 55, 24, 11, 2) + box(15, 61, 70, 18, 4)
        + b(sym(64, [[62, 64, 76, 68, 85, 72], [94, 76, 98, 86, 98, 100]])),
    },
  },
  alien: {
    name: 'alien',
    variants: {
      // A large teardrop skull on a thin neck and narrow, sloping shoulders.
      grey: b(sym(5, [[63, 5, 81, 14, 82, 34], [83, 51, 66, 67, 55, 73], [54, 75, 53, 77, 53.5, 81], [62, 83, 72, 87, 78, 100]])),
      // A wedge head with bulging eyes, antennae, mandibles and a raised foreleg.
      insect: b(sym(22, [[66, 22, 77, 26, 75, 36], [72, 46, 60, 62, 54, 70], [54, 73, 55, 76, 57, 78], [64, 82, 70, 90, 72, 100]]))
        + disc(34, 31, 9) + disc(66, 31, 9)
        + limb('M44 23C40 13 31 7 21 4M56 23C60 13 69 7 79 4M46 68L41 77M54 68L59 77M60 84L86 94M40 84L14 94'),
      // A domed mantle with tentacles hanging below it.
      squid: b(sym(4, [[66, 4, 78, 16, 78, 34], [78, 46, 72, 55, 64, 61]]))
        // Spread outward and never crossing: two tentacles that cross enclose a hole.
        + limb('M40 58C36 72 38 84 30 98M47 58C46 72 45 86 42 100M53 58C54 72 55 86 58 100M60 58C64 72 62 84 70 98'),
      // Swept-back horns, a low crest of spines, a wide jaw narrowing to the
      // chin, a thick neck and high, hunched shoulders.
      reptile: b(sym(6, [
        [55, 6, 60, 9, 62, 12], [66, 11, 70, 13, 71, 17], [76, 14, 82, 8, 88, 4],
        [84, 10, 78, 17, 74, 22], [77, 30, 77, 40, 73, 48], [69, 56, 62, 62, 57, 64],
        [58, 68, 60, 72, 64, 74], [72, 74, 82, 74, 88, 80], [94, 85, 96, 92, 96, 100]]))
        + b('M42 9L46 1L50 7L54 1L58 9Z'),
    },
  },
  robot: {
    name: 'robot',
    variants: {
      // A rounded-top head with small ear cans and two short stubs, one plain
      // neck block, square shoulders. Kept inside the well on every side.
      box: box(39, 7, 3, 7, 1) + box(58, 7, 3, 7, 1)
        + b('M32 30C32 18 38 13 50 13C62 13 68 18 68 30V46H32Z')
        + box(26, 23, 6, 16, 2) + box(68, 23, 6, 16, 2)
        + box(43, 45, 14, 16)
        + b('M16 100V73C16 66 21 60 28 60H72C79 60 84 66 84 73V100Z'),
      // A humanoid machine: a smooth egg-shaped head with flush ear housings,
      // a straight solid neck, a flat collar line and chamfered shoulders.
      // Every part overlaps the next, so no background shows through.
      android: b(sym(10, [
        [62, 10, 70, 19, 70, 31], [70, 42, 65, 52, 57, 56], [57, 56, 57, 65, 57, 65],
        [57, 65, 80, 65, 80, 65], [80, 65, 92, 75, 92, 75], [92, 75, 92, 100, 92, 100]]))
        + box(26, 27, 9, 15, 2) + box(65, 27, 9, 15, 2),
      // A hovering lens with a fin, two rotors on raised arms, a sensor pod
      // underneath and landing skids.
      drone: b('M22 50C22 38 34 30 50 30C66 30 78 38 78 50C78 58 66 64 50 64C34 64 22 58 22 50Z')
        + b('M46 31L50 20L54 31Z')
        + limb('M30 39L16 23M70 39L84 23')
        + b('M2 21C2 18 9 16 16 16C23 16 30 18 30 21C30 24 23 26 16 26C9 26 2 24 2 21Z')
        + b('M70 21C70 18 77 16 84 16C91 16 98 18 98 21C98 24 91 26 84 26C77 26 70 24 70 21Z')
        + disc(50, 68, 7)
        + limb('M37 62L30 84M63 62L70 84') + box(17, 83, 25, 4.5, 2) + box(58, 83, 25, 4.5, 2),
      // A crested helmet with a flared visor edge and chin guard, a collar,
      // exhaust stacks behind the shoulders, angular armour plates.
      mech: b('M47 3H53L55.5 16H44.5Z')
        + b('M40 13H60L69 22L71 38L76 44L75 50L63 58L56 62H44L37 58L25 50L24 44L29 38L31 22Z')
        + b('M38 59H62L67 70H33Z')
        + box(13, 42, 7, 24, 1) + box(80, 42, 7, 24, 1)
        + b('M20 100V78L30 68H70L80 78V100Z')
        + b('M2 94V75L10 62H34L39 71V94Z') + b('M98 94V75L90 62H66L61 71V94Z'),
    },
  },
};
// How much of the well a figure fills: less than all of it, so it has air around it.
const FIGURE_SCALE = 0.8;

const MARKS = { ok: 'ok', note: 'note', bad: 'bad', unknown: 'status unknown' };

// On the well's lower right edge. Shape carries the status, colour repeats it.
const MARK_SHAPES = {
  ok: '<circle class="ov-avatar__mark" cx="85" cy="85" r="11"/>',
  note: '<circle class="ov-avatar__mark" cx="85" cy="85" r="9.5"/>',
  bad: '<path class="ov-avatar__mark" d="M85 71.5L98.5 85 85 98.5 71.5 85Z"/>',
  unknown: '<rect class="ov-avatar__mark" x="75.5" y="75.5" width="19" height="19"/>',
};

let uid = 0;

const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};

export class OvAvatar extends HTMLElement {
  static observedAttributes = ['kind', 'variant', 'name', 'task', 'status'];

  connectedCallback() {
    if (!this._built) this.build();
    this.evaluate();
  }

  attributeChangedCallback() {
    if (this._built) this.evaluate();
  }

  build() {
    this._built = true;
    this._clip = `ov-avatar-clip-${++uid}`;
    this._paint = `ov-avatar-paint-${uid}`;
    this.innerHTML = '<svg class="ov-avatar__pic" viewBox="0 0 100 100" aria-hidden="true"></svg>'
      + '<span class="ov-avatar__text"><span class="ov-avatar__name"></span><span class="ov-avatar__task"></span></span>'
      + '<span class="ov-avatar__note"></span>';
  }

  /* What the slot says, from its attributes alone. Pure. */
  read() {
    const rawKind = this.getAttribute('kind');
    const rawVariant = this.getAttribute('variant');
    const name = (this.getAttribute('name') || '').trim();
    const task = (this.getAttribute('task') || '').trim();
    const rawStatus = this.getAttribute('status');
    const kind = Object.hasOwn(KINDS, rawKind) ? rawKind : null;
    const empty = rawKind === 'unassigned' || (rawKind === null && !name);
    const r = { state: 'assigned', kind, variant: null, name, task, status: null, words: '', ignored: [] };

    if (kind) {
      const names = Object.keys(KINDS[kind].variants);
      if (rawVariant !== null && !names.includes(rawVariant)) r.ignored.push(`variant ${rawVariant}`);
      r.variant = names.includes(rawVariant) ? rawVariant : names[0];
    }

    if (empty && name) {
      r.state = 'conflict';
      r.kind = null;
      r.variant = null;
      r.words = 'NAMED, AND MARKED UNASSIGNED';
    } else if (empty) {
      r.state = 'unassigned';
      r.words = 'UNASSIGNED';
    } else if (!kind) {
      r.state = 'unstated';
      r.words = rawKind === null ? 'KIND NOT STATED' : `KIND ${rawKind.toUpperCase()} IS NOT ONE OF HUMAN, CREW, ALIEN, ROBOT`;
    } else if (!name) {
      r.state = 'unnamed';
      r.words = 'NAME NOT GIVEN';
    }

    // Refusal 4: supplied, never decided, and never on an empty seat.
    if (rawStatus !== null) {
      if (!Object.hasOwn(MARKS, rawStatus)) r.ignored.push(`status ${rawStatus}`);
      else if (r.state === 'unassigned' || r.state === 'conflict') r.ignored.push('status');
      else r.status = rawStatus;
    }
    return r;
  }

  evaluate() {
    const r = this.read();
    this._report = r;
    const q = (k) => this.querySelector(`.ov-avatar__${k}`);

    let pic = '';
    if (r.state === 'unassigned') {
      pic = '<rect class="ov-avatar__well" x="2" y="2" width="96" height="96" rx="12"/>'; /* MUTANT */
    } else if (r.state === 'unstated' || r.state === 'conflict') {
      pic = '<rect class="ov-avatar__slot is-unstated" x="3" y="3" width="94" height="94" rx="12"/>'
        + '<text class="ov-avatar__q" x="50" y="65">?</text>';
    } else {
      // One gentle vertical gradient per avatar, in the well's own units so a
      // straight limb (zero-width box) is painted too: lighter at the head,
      // darker toward the shoulders. The colours are stylesheet tokens.
      pic = `<clipPath id="${this._clip}"><rect x="2" y="2" width="96" height="96" rx="12"/></clipPath>`
        + `<linearGradient id="${this._paint}" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="100">`
        + '<stop class="ov-avatar__stop-top" offset="0"/><stop class="ov-avatar__stop-bottom" offset="1"/></linearGradient>'
        + '<rect class="ov-avatar__well" x="2" y="2" width="96" height="96" rx="12"/>'
        + `<g clip-path="url(#${this._clip})" style="--ov-av-paint:url(#${this._paint})">`
        // Scaled down about the bottom centre, so the figure keeps its portrait
        // crop at the well's lower edge and gains room above and to the sides.
        + `<g class="ov-avatar__fig" transform="translate(50 100) scale(${FIGURE_SCALE}) translate(-50 -100)">${KINDS[r.kind].variants[r.variant]}</g></g>`;
    }
    if (r.status) pic += MARK_SHAPES[r.status];
    const svg = q('pic');
    if (svg.innerHTML !== pic) svg.innerHTML = pic;

    setAttr(this, 'data-ov-avatar', r.state);
    setAttr(this, 'data-ov-kind', r.kind);
    setAttr(this, 'data-ov-variant', r.variant);
    setAttr(this, 'data-ov-status', r.status);
    setAttr(this, 'data-ov-refusal', r.state === 'assigned' ? null : 'unknown');

    const nameLine = r.state === 'unnamed' ? 'NAME NOT GIVEN' : r.state === 'unassigned' ? 'UNASSIGNED' : r.name;
    setText(q('name'), nameLine);
    const second = r.state === 'unstated' || r.state === 'conflict' ? r.words : r.state === 'unassigned' ? '' : r.task;
    setText(q('task'), second);
    const variantNote = r.ignored.find((x) => x.startsWith('variant '));
    const other = r.ignored.filter((x) => x !== 'status' && !x.startsWith('variant '));
    setText(q('note'), r.ignored.includes('status') ? 'A STATUS FOR AN EMPTY SLOT IS NOT SHOWN'
      : variantNote && r.kind ? `${variantNote.toUpperCase()} IS NOT A ${KINDS[r.kind].name.toUpperCase()} VARIANT`
        : other.length ? `NOT SHOWN: ${other.join(', ').toUpperCase()}` : '');

    this.setAttribute('role', 'img');
    const drawn = r.kind ? `${r.variant === 'neutral' || r.kind === 'crew' ? '' : `${r.variant} `}${KINDS[r.kind].name}` : 'kind not stated';
    const who = r.state === 'unassigned' ? 'unassigned slot' : `${r.name || 'name not given'}, ${drawn}`;
    this.setAttribute('aria-label', `${who}${r.state === 'conflict' ? ', named and marked unassigned' : ''}`
      + `${r.task && r.state !== 'unassigned' ? `, ${r.task}` : ''}${r.status ? `, ${MARKS[r.status]}` : ''}`);
  }

  get report() { return this._report || null; }
}

define('ov-avatar', OvAvatar);
